// CreateSession queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateSession(parent string, in *eventpbv1.Session) (string, error) {
	r := &GraphQLSessionRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueSessionReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if err := r.linkParents(ctx, &ci, named.GetName(), b.keys); err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Event.Sessions.CreateOp(ci, new(sessionsql.InsertEventSessionsResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "aperio.event.v1/Session", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

